    const fail = e => { st.my.wx = null; const i = $('MyWxInfo'); const lat = /latitude/i.test(e.message); if (i) i.innerHTML = '<span style="color:#b3261e"><b>Not used:</b> ' + esc(e.message) + '</span>' + (lat ? '<br><span class="pnote">Your weather has no solar radiation, so Daisy needs the latitude of your site to work it out from the daily minimum and maximum temperature. Type it in the box <b>Site: latitude</b> just above (degrees north, negative in the south); the weather is read again as soon as you leave the box. No place name? Choose "Online weather" once, press Find, and the latitude is filled in.</span>' : ''); if (lat) { const b = document.querySelector('#dzMyBox [data-my="lat"]'); if (b) { b.style.outline = '2px solid #b3261e'; b.focus(); b.addEventListener('input', () => { b.style.outline = ''; }, { once: true }); } } };
    sel.onchange = () => { m.wxMode = sel.value; $('MyWxF').style.display = m.wxMode === 'file' ? '' : 'none'; $('MyOn').style.display = m.wxMode === 'online' ? '' : 'none'; $('MyLoc').style.display = m.wxMode === 'course' ? 'none' : ''; m.wx = null; $('MyWxInfo').innerHTML = wxInfo(); if (m.wxMode === 'project') { fromProject().catch(fail); } };
    const hits = []; $('MyFind').onclick = async () => { const q = $('MyPlace').value.trim(); if (!q) return; m.place = q; $('MyWxInfo').textContent = 'Looking for ' + q + '...'; try { const r = await DaisyOnline.geocode(q); hits.length = 0; r.forEach(x => hits.push(x)); const h = $('MyHits'); if (!r.length) { h.style.display = 'none'; throw new Error('no place of that name was found; try another spelling or type the latitude and longitude'); } h.innerHTML = r.map((x, i) => '<option value="' + i + '">' + esc(x.label) + ' (' + x.lat.toFixed(2) + ', ' + x.lon.toFixed(2) + ')</option>').join(''); h.style.display = ''; pick(); $('MyWxInfo').textContent = r.length + ' place(s) found; press "Get the weather".'; } catch (e) { fail(e); } };
    const pick = () => { const x = hits[+$('MyHits').value]; if (!x) return; m.lat = +x.lat.toFixed(3); m.lon = +x.lon.toFixed(3); m.elev = x.elev != null ? Math.round(x.elev) : m.elev; document.querySelectorAll('#dzMyBox [data-my]').forEach(i => { if (m[i.dataset.my] !== undefined) i.value = m[i.dataset.my]; }); };
    $('MyHits').onchange = pick;
    $('MyGet').onclick = async () => { try { readMyInputs(); if (m.lat === '' || m.lon === '') throw new Error('give a place (press Find) or the latitude and longitude'); const y0 = +$('MyY0').value, y1 = +$('MyY1').value; m.y0 = y0; m.y1 = y1; if (!(y1 - y0 >= 5)) throw new Error('ask for at least six years: Daisy starts one year after the weather begins'); $('MyWxInfo').textContent = 'Getting the weather from the internet...'; const src = await DaisyOnline.fetchDaily(+m.lat, +m.lon, y0, y1); if (src.elevation != null && m.elev === '') m.elev = Math.round(src.elevation); const nm = (m.place || 'Online weather') + ' ' + (+m.lat).toFixed(2) + 'N ' + (+m.lon).toFixed(2) + 'E'; convertWx(src, nm); m.wx.quality = src.stats; m.wx.cite = 'weather: Open-Meteo archive, ERA5 reanalysis (Zippenfenig, 2023; Hersbach et al., 2020), ' + (+m.lat).toFixed(2) + 'N ' + (+m.lon).toFixed(2) + 'E'; } catch (e) { fail(new Error((/fetch|network|Failed/i.test(e.message) ? 'no connection to the weather service (' + e.message + '). Use a weather file instead, or try again online.' : e.message))); } };
    $('MyFile').onchange = ev => { const f = ev.target.files[0]; if (!f) return; const r = new FileReader(); r.onload = () => { fromText(f.name, String(r.result)).catch(fail); }; r.readAsText(f); };
    document.querySelectorAll('#dzMyBox [data-my]').forEach(i => i.onchange = () => { readMyInputs(); if (m.wxMode === 'project') { fromProject().catch(fail); } else if (m.wxMode === 'file' && $('MyFile').files[0]) $('MyFile').onchange({ target: $('MyFile') }); });
    $('MySoilOn').onchange = ev => { readMyInputs(); m.soilOn = ev.target.checked; const vu = $('VUser'); if (vu) vu.style.display = m.soilOn ? '' : 'none'; $('MySoil').style.display = m.soilOn ? '' : 'none'; const s = document.querySelector('#dzSPanel [data-o="soil"]'); if (s) s.disabled = m.soilOn; };
