    if (m.wx && (m.wxMode === 'online' || m.wxMode === 'file')) h += '<option value="' + m.wxMode + '" selected>' + (m.wxMode === 'online' ? 'Online weather: ' : 'My file: ') + esc(m.wx.name) + '</option>';
