    g += R(465, 22, 115, 100, '#cfe6a5') + T(522, 44, 'Vegetation', { b: 1, s: 15 }) + lines(522, 62, ['Growth', 'Photosynthesis', 'Respiration', 'Uptake'], { s: 11 });
    g += A(425, 72, 465, 72, 1) + A(330, 122, 330, 150, 1) + A(522, 122, 522, 150, 1);
