  const REPOS = [['daisy', 'The model itself (C++), library of soils, crops and fertilisers', 'Library tab; the program the scenarios run'], ['daisy-r-tools', 'R tools for logs (read, mass balance, plots)', 'Files, Plot and Mass balance tabs'], ['daisypy-io', 'Read and write Daisy files in Python', 'File readers of the workbench'], ['daisypy-vis', 'Visualisation of Daisy output', 'Figure gallery'], ['daisypy-test', 'Comparison of runs against the smallest meaningful level', 'Compare and test tab'], ['daisypy-optim', 'Calibration: sequential, CMA-ES, Bayesian', 'Calibrate tab'], ['python-extensions', 'Chemical reactions in Python (denitrification)', 'Denitrification tab'], ['python-dmi-open-data', 'Danish Meteorological Institute open data', 'Weather tab (DMI)'], ['richards-equation', 'Solvers for the Richards equation', 'Soil column tab'], ['daisy-vscode', 'Daisy in Visual Studio Code', 'Set-up editor'], ['geodaisy', 'Daisy and maps', 'Field map of SWAFL'], ['tools', 'Utilities', '']];
  function docsHtml() {
    const plat = /Win/i.test(navigator.platform) ? 'win' : /Mac/i.test(navigator.platform) ? 'mac' : 'lin';
    return '<div class="dzpan"><h3 style="margin:0">The Daisy model</h3><p>Daisy is a process-based model of the soil-plant-atmosphere system for managed fields. It calculates water, heat, carbon and nitrogen balances and the fate of chemicals, with a crop growing on a soil column that is solved with the Richards equation. It has been used in about 120 studies of crop production, nitrogen leaching, nitrous oxide, irrigation, carbon and pesticides (Holbak et al. 2026, <i>Agricultural Systems</i> 238, 104846). In SWAFL every Daisy question becomes a scenario: choose what to find out, adjust the options, run, and read the figures.</p>' + diagram() + '</div>' +
      '<div class="dzpan"><h3 style="margin:0">Which question is answered where</h3><table class="dzt"><tr><th>Theme of the Daisy studies</th><th>Where in SWAFL</th></tr><tr><td>Nitrogen: fertilisation, leaching, N2O</td><td>Scenario Nitrogen; Denitrification tab</td></tr><tr><td>Crop and climate: yield, stress, warming</td><td>Scenario Climate</td></tr><tr><td>Water: irrigation, tillage and soil, energy fluxes</td><td>Scenarios Irrigation and Soil; Soil column tab; the SWAFL irrigation layers</td></tr><tr><td>Carbon: organic matter, carbon balance</td><td>Set-up editor with your own .dai; Mass balance tab on organic-matter logs</td></tr><tr><td>Chemicals: pesticides, PFAS, natural toxins</td><td>Scenario Chemical</td></tr></table></div>' +
      '<div class="dzpan"><h3 style="margin:0">Get Daisy 7.1.14</h3><p class="pnote">The scenarios run the real Daisy program, so install it on the computer that runs the SWAFL desktop app, then use <i>Choose the Daisy program</i> once in the Scenarios tab. SWAFL finds a program on the PATH or in the usual folders by itself, and also a <b>daisy</b> folder put beside the app (daisy/bin/daisy or daisy/daisy.exe with its lib folder), so a copy on a memory stick runs with no installation and no network. Without the program the web version and the desktop app still plan experiments, write the complete Daisy folder (run_all.sh and run_all.bat) and explore the 10 190 published runs offline. Check the download against the sha256 value.</p><table class="dzt"><tr><th>System</th><th>File</th><th>Size</th><th>sha256</th></tr>' + ASSETS.map(a => '<tr' + (a[4] === plat ? ' style="background:#e8f2ff"' : '') + '><td>' + a[0] + '</td><td><a href="#" data-url="' + REL + a[1] + '">' + a[1] + '</a></td><td>' + a[2] + '</td><td style="font:10px Consolas,monospace">' + a[3] + '</td></tr>').join('') + '</table><p>' + DOCS.map(d => '<a href="#" data-url="' + REL + d[0] + '">' + d[0] + '</a> ' + d[2] + ' - ' + esc(d[1])).join('<br>') + '<br><a href="#" data-url="https://github.com/daisy-model/daisy/releases">All Daisy releases</a> &middot; <a href="#" data-url="https://doi.org/10.1016/j.agsy.2026.104846">The review of the Daisy model (open access)</a> &middot; <a href="#" data-url="https://github.com/daisy-model">The daisy-model organisation (12 repositories)</a></p></div>' +
      '<div class="dzpan"><h3 style="margin:0">The 12 daisy-model repositories and what SWAFL uses them for</h3><table class="dzt"><tr><th>Repository</th><th>Purpose</th><th>In SWAFL</th></tr>' + REPOS.map(r => '<tr><td><a href="#" data-url="https://github.com/daisy-model/' + r[0] + '">' + r[0] + '</a></td><td>' + esc(r[1]) + '</td><td>' + esc(r[2]) + '</td></tr>').join('') + '</table></div>' +
      '<div class="dzpan"><h3 style="margin:0">How a Daisy time step is calculated</h3><ol class="pnote" style="font-size:13px"><li>Initialise the soil, crop and weather.</li><li>Sink terms of the drains and biopores; find the time step.</li><li>Bioclimate, crop growth and heat flow (the soil-vegetation-atmosphere module).</li><li>Crop uptake of chemicals, above-ground chemical flow, organic matter turnover.</li><li>Richards equation, with the time step reduced until it converges.</li><li>Chemical reactions (nitrification, denitrification), adsorption, advection and dispersion.</li><li>Repeat until the end of the simulation.</li></ol></div>';
  }
  function docsBind() { document.querySelectorAll('#dzBody a[data-url]').forEach(a => a.onclick = ev => { ev.preventDefault(); UI.openExternal(a.dataset.url); }); }

  const css = '.dzcards{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:8px;margin:8px 0}.dzcard{border:1px solid #c3cad6;border-radius:8px;padding:9px 11px;cursor:pointer;background:#fff;display:flex;flex-direction:column;gap:4px}.dzcard:hover{border-color:#0072B2;box-shadow:0 1px 6px rgba(0,114,178,.25)}.dzcard.on{border:2px solid #0072B2;background:#eef6fc}.dzchip{align-self:flex-start;font-size:10.5px;background:#0072B2;color:#fff;border-radius:9px;padding:1px 8px}.dzchip2{background:#6b7a8c}.dzpan{border:1px solid #d5d9e0;border-radius:8px;background:#fff;padding:10px 12px;margin:8px 0}.dzvars{display:flex;flex-direction:column;gap:3px;margin-top:3px}.dzrun{padding:2px 0}.dzspin{display:inline-block;width:11px;height:11px;border:2px solid #0072B2;border-top-color:transparent;border-radius:50%;animation:dzs 0.8s linear infinite;vertical-align:-1px}@keyframes dzs{to{transform:rotate(360deg)}}';
  const st2 = document.createElement('style'); st2.textContent = css; document.head.appendChild(st2);
  // weather of the user's area for other tabs (Experiments): find the place, get the daily data from the internet, convert it to a Daisy weather file
  async function onlineWx(place, y0, y1) {
    const m = st.my; m.wxMode = 'online'; if (place) { const r = await DaisyOnline.geocode(place); if (!r.length) throw new Error('no place of that name was found; try another spelling'); const x = r[0]; m.lat = +x.lat.toFixed(3); m.lon = +x.lon.toFixed(3); m.elev = x.elev != null ? Math.round(x.elev) : m.elev; m.place = place; }
    if (m.lat === '' || m.lat == null || m.lon === '' || m.lon == null) throw new Error('give a place name'); if (!(y1 - y0 >= 5)) throw new Error('ask for at least six years: Daisy starts one year after the weather begins'); m.y0 = y0; m.y1 = y1;
    let src; try { src = await DaisyOnline.fetchDaily(+m.lat, +m.lon, y0, y1); } catch (e) { throw new Error(/Failed to fetch|NetworkError|Load failed|network/i.test(e.message) ? 'no connection to the weather service (' + e.message + '). Use a weather file in My data instead, or try again online.' : e.message); }
    if (src.elevation != null && (m.elev === '' || m.elev == null)) m.elev = Math.round(src.elevation); convertWx(src, (m.place || 'Online weather') + ' ' + (+m.lat).toFixed(2) + 'N ' + (+m.lon).toFixed(2) + 'E'); m.wx.quality = src.stats; m.wx.cite = 'weather: Open-Meteo archive, ERA5 reanalysis (Zippenfenig, 2023; Hersbach et al., 2020), ' + (+m.lat).toFixed(2) + 'N ' + (+m.lon).toFixed(2) + 'E'; return m.wx;
  }
  window.DaisyScenUI = { online: onlineWx, project: useProject, projectName: () => { const w = projWx(); return w ? (w.name || w.src || 'loaded') : null; }, onWx: h => wxHooks.push(h), defaultWx, useFile: (act, name, text) => { st.pending = { act, name, text }; D.show('data'); }, runStandard, my: () => st.my, strip, bindStrip, runs: () => st.runs, sc: () => st.sc, dataLabel: () => ({ weather: wxLabel().replace(/<[^>]+>/g, ''), soil: soilLabel() }) };
